"""Helper classes and functions."""

import os

from jsilib import _utils
from jsilib.aio import helpers as aio_helpers
from jsilib.aio.interface import IReactor

from . import exc as jsi_exc
from .interface import IJSICachedMessage, IJSIMessage
from .messages import JSIBytesMessage, JSIStreamMessage

__all__ = export = _utils.ExportList()


@export
async def create_cached_message(
    reactor: IReactor,
    source: IJSIMessage,
    read_chunk_size: int = 4096,
    in_memory_limit: int = 2 * 1024 * 1024
) -> IJSICachedMessage:
    """Create cached message from given *source*.

    Rationale for this helper is that instances of :class:`IJSIMessage` can
    only be read once, while in some situations (like notifications) it is
    needed to share same message between several users. This helper does that
    by reading entire *source* message and creating a cache for it (either
    in-memory or as a temporary file), that can later be read from.

    :param source:
        Message to create cache from

    :param read_chunk_size:
        Maximal number of bytes to read from *source* during single read
        operation.

    :param in_memory_limit:
        Maximal size of a *source* message that can fit into an in-memory
        storage.

        For messages smaller than this limit, there will be a faster, in-memory
        cache used, while for larger it will be a temporary file created that
        later will be read from.
    """
    if source.size() < in_memory_limit:
        cache = _InMemoryJSICachedMessage(source, read_chunk_size)
    else:
        cache = _TempFileJSICachedMessage(reactor, source, read_chunk_size)
    await cache.fill()
    return cache


class _InMemoryJSICachedMessage(IJSICachedMessage):

    def __init__(self, source: IJSIMessage, read_chunk_size: int):
        self._source = source
        self._read_chunk_size = read_chunk_size

    async def fill(self):
        self._payload = await aio_helpers.read_all(self._source, self._source.bytes_left())

    def is_closed(self) -> bool:
        return self._payload is None

    async def close(self):
        self._payload = None

    async def acquire(self) -> IJSIMessage:
        if self._payload is None:
            raise jsi_exc.MessageCacheClosedError()
        return JSIBytesMessage(self._payload)


class _TempFileJSICachedMessage(IJSICachedMessage):

    def __init__(self, reactor: IReactor, source: IJSIMessage, read_chunk_size: int):
        self._reactor = reactor
        self._source = source
        self._read_chunk_size = read_chunk_size

    @property
    def _cache_file_path(self):
        return os.path.join(self._tmpdir.path, 'message.dat')

    async def fill(self):
        self._tmpdir = await aio_helpers.create_temporary_directory(self._reactor)
        dest = await aio_helpers.open_file(self._reactor, self._cache_file_path, 'w')
        async with self._source:
            async with dest:
                await aio_helpers.copy_all(self._source, dest, self._source.size())

    def is_closed(self) -> bool:
        return self._tmpdir.is_closed()

    async def close(self):
        await self._tmpdir.close()

    async def acquire(self) -> IJSIMessage:
        if self.is_closed():
            raise jsi_exc.MessageCacheClosedError()
        return JSIStreamMessage(
            await aio_helpers.open_file(self._reactor, self._cache_file_path, 'r'), self._source.size()
        )
